1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const COMPONENT_TYPES = ["rune", "moonstone"];
68	const BLOCK_SIZE = 3;
69	const BLOCK_BASE_PREMIUM = 60;
70	const CURSE_SURCHARGE_RATE = 0.5;
71	
72	const sum = (amounts: number[]): number => amounts.reduce((total, a) => total + a, 0);
73	
74	/** Rounds to whole G in the MHPCO's favour. */
75	const roundUpToWholeG = (amount: number): number => Math.ceil(amount);
76	
77	const groupByType = (items: Item[]): Map<string, Item[]> => {
78	  const groups = new Map<string, Item[]>();
79	  for (const item of items) {
80	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
81	  }
82	  return groups;
83	};
84	
85	const basePremiumForItem = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
86	
87	/**
88	 * Components are priced per group of alike items, because a building block of
89	 * exactly 3 alike components earns a special rate. Main items price per item.
90	 */
91	const basePremiumForGroup = (type: string, group: Item[]): number => {
92	  if (COMPONENT_TYPES.includes(type) && group.length === BLOCK_SIZE) {
93	    return BLOCK_BASE_PREMIUM;
94	  }
95	  return sum(group.map(basePremiumForItem));
96	};
97	
98	/** Item-specific surcharges apply to the affected item's own base premium. */
99	const itemSurcharges = (item: Item): number =>
100	  item.cursed ? basePremiumForItem(item) * CURSE_SURCHARGE_RATE : 0;
101	
102	const quotePremium = (items: Item[]): number => {
103	  const policyBasePremium = sum(
104	    [...groupByType(items)].map(([type, group]) => basePremiumForGroup(type, group)),
105	  );
106	  const itemSurchargeTotal = sum(items.map(itemSurcharges));
107	  const initialAssessmentSurcharge = policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
108	  return roundUpToWholeG(
109	    policyBasePremium + itemSurchargeTotal + initialAssessmentSurcharge + PROCESSING_FEE,
110	  );
111	};
112	
113	export const runScenario = (scenario: Scenario): ScenarioResult => {
114	  return {
115	    results: scenario.steps.map((step) => ({
116	      premium: quotePremium((step as QuoteStep).items),
117	    })),
118	  };
119	};
