1	import { describe, it, expect } from "vitest";
2	import { runScenario, type Scenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  describe("quote — base premiums", () => {
6	    it("empty item list → premium 5 G (only the processing fee)", () => {
7	      const scenario: Scenario = {
8	        customer: { yearsWithMHPCO: 0 },
9	        steps: [{ op: "quote", items: [] }],
10	      };
11	
12	      expect(runScenario(scenario)).toEqual({ results: [{ premium: 5 }] });
13	    });
14	    // premium = base + 10 % initial assessment surcharge + 5 G processing fee
15	    it.each([
16	      { type: "sword", base: 100, premium: 115 },
17	      { type: "amulet", base: 60, premium: 71 },
18	      { type: "staff", base: 80, premium: 93 },
19	      { type: "potion", base: 40, premium: 49 },
20	      { type: "rune", base: 25, premium: 33 },
21	      { type: "moonstone", base: 25, premium: 33 },
22	    ])("a single $type → base premium $base G", ({ type, premium }) => {
23	      const scenario: Scenario = {
24	        customer: { yearsWithMHPCO: 0 },
25	        steps: [{ op: "quote", items: [{ type }] }],
26	      };
27	
28	      expect(runScenario(scenario)).toEqual({ results: [{ premium }] });
29	    });
30	  });
31	
32	  describe("quote — building block of 3 alike components", () => {
33	    it("2 runes → 50 G base premium", () => {
34	      const scenario: Scenario = {
35	        customer: { yearsWithMHPCO: 0 },
36	        steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
37	      };
38	
39	      // 2 × 25 = 50 base (no block: requires exactly 3)
40	      // 50 + 5 initial assessment = 55, + 5 fee = 60
41	      expect(runScenario(scenario)).toEqual({ results: [{ premium: 60 }] });
42	    });
43	    it("3 runes → 60 G base premium (block applies)", () => {
44	      const scenario: Scenario = {
45	        customer: { yearsWithMHPCO: 0 },
46	        steps: [
47	          { op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] },
48	        ],
49	      };
50	
51	      // block of 3 alike components → 60 base (not 3 × 25 = 75)
52	      // 60 + 6 initial assessment = 66, + 5 fee = 71
53	      expect(runScenario(scenario)).toEqual({ results: [{ premium: 71 }] });
54	    });
55	    it("4 runes → 100 G base premium (no block — block requires exactly 3)", () => {
56	      const scenario: Scenario = {
57	        customer: { yearsWithMHPCO: 0 },
58	        steps: [{ op: "quote", items: Array.from({ length: 4 }, () => ({ type: "rune" })) }],
59	      };
60	
61	      // 4 × 25 = 100 base (the block does not apply to a subset of 3)
62	      // 100 + 10 initial assessment = 110, + 5 fee = 115
63	      expect(runScenario(scenario)).toEqual({ results: [{ premium: 115 }] });
64	    });
65	    it("7 runes → 175 G base premium", () => {
66	      const scenario: Scenario = {
67	        customer: { yearsWithMHPCO: 0 },
68	        steps: [{ op: "quote", items: Array.from({ length: 7 }, () => ({ type: "rune" })) }],
69	      };
70	
71	      // 7 × 25 = 175 base (the block does not repeat: not 2 blocks + 1)
72	      // 175 + 17.5 initial assessment = 192.5, + 5 fee = 197.5 → rounds up to 198
73	      expect(runScenario(scenario)).toEqual({ results: [{ premium: 198 }] });
74	    });
75	    it("2 runes + 1 moonstone → 75 G base premium (no block: different types)", () => {
76	      const scenario: Scenario = {
77	        customer: { yearsWithMHPCO: 0 },
78	        steps: [
79	          {
80	            op: "quote",
81	            items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
82	          },
83	        ],
84	      };
85	
86	      // Pins "alike" = the SAME TYPE, not the same family: 3 components but
87	      // no block, because the rune group is 2 and the moonstone group is 1.
88	      // 3 × 25 = 75 base; 75 + 7.5 = 82.5, + 5 fee = 87.5 → rounds up to 88
89	      expect(runScenario(scenario)).toEqual({ results: [{ premium: 88 }] });
90	    });
91	    it("3 runes + 3 moonstones → 120 G base premium (two separate blocks)", () => {
92	      const scenario: Scenario = {
93	        customer: { yearsWithMHPCO: 0 },
94	        steps: [
95	          {
96	            op: "quote",
97	            items: [
98	              ...Array.from({ length: 3 }, () => ({ type: "rune" })),
99	              ...Array.from({ length: 3 }, () => ({ type: "moonstone" })),
100	            ],
101	          },
102	        ],
103	      };
104	
105	      // each type forms its own block: 60 + 60 = 120 base
106	      // 120 + 12 initial assessment = 132, + 5 fee = 137
107	      expect(runScenario(scenario)).toEqual({ results: [{ premium: 137 }] });
108	    });
109	  });
110	
111	  describe("quote — item-specific modifiers", () => {
112	    it("cursed sword → 50 % risk surcharge on that item's base premium", () => {
113	      const scenario: Scenario = {
114	        customer: { yearsWithMHPCO: 0 },
115	        steps: [
116	          {
117	            op: "quote",
118	            items: [{ type: "sword", material: "steel", enchantment: 3, cursed: true }],
119	          },
120	        ],
121	      };
122	
123	      // Spec's "Newcomer with a cursed sword" integration example:
124	      // 100 G base + 50 G curse + 10 G first insurance = 160 G + 5 G fee = 165 G
125	      // Note the 10 G is 10 % of the policy BASE premium (100), not of 150 —
126	      // policy-wide modifiers apply to the sum of item base premiums.
127	      expect(runScenario(scenario)).toEqual({ results: [{ premium: 165 }] });
128	    });
129	    it.todo("sword with enchantment 5 → 30 % high-enchantment surcharge applies");
130	    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
131	    it.todo("cursed sword with enchantment 5 → both surcharges apply");
132	  });
133	
134	  describe("quote — policy-wide modifiers", () => {
135	    it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
136	    it.todo("customer with 1 year with MHPCO → no loyalty discount");
137	    it.todo("first insurance → 10 % initial assessment surcharge on the policy base premium");
138	    it.todo("the customer's second quote → additional 15 % follow-up contract discount");
139	  });
140	
141	  describe("quote — modifier scope on multi-item policies", () => {
142	    it.todo(
143	      "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G; curse adds 50 G (50 % of the cursed item only) → 210 G before further modifiers and fee",
144	    );
145	  });
146	
147	  describe("quote — rounding in the MHPCO's favour", () => {
148	    it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
149	    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
150	  });
151	
152	  describe("claim — standard reimbursement", () => {
153	    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
154	    it.todo("damage to a rune (no enchantment or material), damage 200 G → payout 100 G");
155	  });
156	
157	  describe("claim — special clauses", () => {
158	    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (dragon clause only)");
159	    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % clause, then deductible)");
160	    it.todo("dragon-material sword, enchantment 8, damage 1000 G → payout 400 G (50 % clause at the threshold)");
161	    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins over dragon material)");
162	  });
163	
164	  describe("claim — deductible per damage event", () => {
165	    it.todo(
166	      "a dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (100 G deductible once per damaged item)",
167	    );
168	    it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
169	  });
170	
171	  describe("claim — insurance sum and cap", () => {
172	    it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
173	    it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
174	    it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G, cap 3500 G (block affects premium only)");
175	    it.todo("a cursed sword → cap 2000 G based on the unmodified insurance value (premium modifiers do not raise the cap)");
176	    it.todo("sword (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
177	    it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G (reduced to the remaining cap)");
178	  });
179	
180	  describe("claim — multiple items of the same type", () => {
181	    it.todo(
182	      "a policy covers two swords; two sword damage entries → each entry is a separate damage with its own deductible",
183	    );
184	    it.todo("more damage entries of a type than the policy covers (two sword damages, one sword insured) → error");
185	  });
186	
187	  describe("errors", () => {
188	    it.todo("quote includes an item with an unknown type (e.g. broomstick) → error");
189	    it.todo("claim references a damage entry whose item is not part of the policy (amulet damaged, only a sword insured) → error");
190	    it.todo("claim references a damage entry with an unknown item type → error");
191	    it.todo("claim contains a damage entry with amount -200 → error");
192	  });
193	
194	  describe("integration examples", () => {
195	    it.todo("newcomer (0 years, no previous contract) with a cursed steel sword (enchantment 3) → premium 165 G");
196	    it.todo("long-standing customer (3 years), second quote, cursed steel sword (enchantment 7) → premium 160 G");
197	  });
198	});
